/* Pizza Lab browser client; server owns every secret and every persistent mutation. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>x==null||x===''?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:2});
const n=x=>x===''||x==null?null:Number(x);
const money=x=>x==null?'—':Number(x).toFixed(1);
const field=(name,label,value='',type='number',more='')=>`<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value??'')}" ${more}></label>`;
const option=(val,label,sel)=>`<option value="${esc(val)}" ${String(val)===String(sel)?'selected':''}>${esc(label)}</option>`;
const timerStorageKey='pizzalab_timers_v2_'+String(typeof window==='undefined'?'test':(window.PIZZA_LAB.user_id||'unknown'));
const state={page:'overview',data:{recipes:[],batches:[],evidence:[],counts:{}},detail:null,activeEvidence:0,stream:null,mediaRecorder:null,audioChunks:[],recorded:null,previewTimer:null,scanner:false,scanning:false,scans:0,scanInterval:null,playing:false,timers:{},timer:{running:false,start:0,elapsed:0,duration:480,cues:{},testId:0},sound:false,voice:true,pull:45,turn:120,log:[],cameraBusy:false,voiceProfile:null,pendingBatchId:null,activeBatch:null,batchFilter:'all',batchMakerFilter:'all',recognizer:null,listening:false,wantsListen:false,speakingUntil:0,lastTranscript:'',processRecipeId:null,activeExperiment:null,labAnalytics:null};
function toast(message,alert=false){const x=document.createElement('div');x.className='toast'+(alert?' alert':'');x.textContent=message;$('#toasts').prepend(x);setTimeout(()=>x.remove(),6500);}
async function api(action,body=null){const opts=body===null?{}:{method:'POST',headers:{'X-CSRF-Token':window.PIZZA_LAB.csrf}};if(body instanceof FormData){body.set('action',action);opts.body=body;}else if(body){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify({action,...body});}
 const res=await fetch('api.php'+(body===null?'?action='+encodeURIComponent(action):''),opts);let json;try{json=await res.json();}catch{throw Error('Server returned an invalid response');}if(!res.ok||!json.ok)throw Error(json.error||'Request failed');return json;}
async function refresh(){const j=await api('bootstrap');state.data=j;return j;}
const recipe=id=>state.data.recipes.find(x=>+x.id===+id);
const stepsFor=id=>(state.data.recipe_steps||[]).filter(x=>+x.recipe_id===+id).sort((a,b)=>+a.sort_order-+b.sort_order);
const ev=id=>state.data.evidence.find(x=>+x.id===+id);
const batch=id=>state.data.batches.find(x=>+x.id===+id);
const selectRecipes=(selected)=>state.data.recipes.map(r=>option(r.id,r.name,selected)).join('');
const selectBatches=(selected,includeArchived=false)=>state.data.batches.filter(b=>includeArchived||b.stage!=='archived').map(b=>option(b.id,`${b.batch_code} · ${b.label||b.recipe_name||'Batch'} (${b.recipe_name})`,selected)).join('');
const batchMakerOptions=(selected)=> (state.data.batch_makers||[]).filter(u=>Number(u.is_active)===1||String(u.id)===String(selected)).map(u=>option(u.id,u.display_name+(Number(u.is_active)===1?'':' (inactive; historical)'),selected)).join('');
const makerLabel=b=>b.made_by_name||'Not recorded';
const selectEvidence=(selected)=>state.data.evidence.map(e=>option(e.id,`#${e.id} · ${e.label}`,selected)).join('');
const tags=(arr)=>arr.map(x=>`<span class="pill">${esc(x)}</span>`).join('');
function head(title,desc,action=''){return `<div class="section-head"><div><p class="overline">DOUGH & OVEN INTELLIGENCE</p><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function panel(title,body){return `<section class="panel"><h2>${title}</h2><div class="mt">${body}</div></section>`;}
function metrics(r){const flour=+r.flour_g;return flour?`<div class="recipe-metrics">${[['Hydration',r.water_g],['Salt',r.salt_g],['Yeast',r.yeast_g],['Honey',r.honey_g]].map(([k,v])=>`<span>${k} <strong>${v===null?'—':(+v/flour*100).toFixed(2)+'%'}</strong></span>`).join('')}</div>`:'<span class="pill amber">Incomplete formula</span>';}
function overview(){const {counts,evidence,recipes}=state.data;return head('A better pizza, proven.','Recipes, stone temperatures, bake evidence, and AI observations in one place.',`<button class="primary" data-go="live">◎ Start live oven session →</button>`)+
`<div class="grid-4 mb"><div class="metric"><small>RECIPE FORMULAS</small><strong>${num(counts.recipes)}</strong><div class="foot">Current + experimental</div></div><div class="metric"><small>PIZZA TESTS</small><strong>${num(counts.tests)}</strong><div class="foot">With cook conditions</div></div><div class="metric"><small>EVIDENCE PHOTOS</small><strong>${num(counts.photos)}</strong><div class="foot">Top · bottom · side</div></div><div class="metric"><small>AI VISION</small><strong>${state.data.settings.key_configured?'<span class="green">Ready</span>':'<span class="accent">Setup</span>'}</strong><div class="foot">${state.data.settings.key_configured?'Claude key configured':(window.PIZZA_LAB.role==='super_admin'?'Configure server-side API key':'Ask your Super Admin to configure Claude')}</div></div></div>
<div class="notice-strip mb">Dough batches: <b>${num(counts.batches||0)}</b> tracked mixes. <button data-go="batches" class="sm">Open batch tracker →</button></div>
<div class="grid-2">${panel('Latest pizza evidence',evidence.length?`<div class="quick-list">${evidence.slice(0,6).map(e=>`<button data-detail="${e.id}"><span><b>${esc(e.label)}</b><small style="display:block">${esc(e.recipe_name||'No recipe assigned')} · ${esc((e.created_at||'').slice(0,16))}</small></span><span>→</span></button>`).join('')}</div>`:`<div class="empty">No tests yet.<br><button class="primary mt" data-go="evidence">Create your first pizza test</button></div>`)}${panel('Recipe development',`<p class="muted">Keep your actual work dough separate from the proposed 85 g fresh yeast experiment.</p><div class="quick-list">${recipes.slice(0,5).map(r=>`<button data-edit-recipe="${r.id}"><span><b>${esc(r.name)}</b><small style="display:block">${esc(r.flour_name||'Ingredients not entered')}</small></span><span>→</span></button>`).join('')}</div>`)}
</div><div class="notice-strip mt"><b>Measurement rule:</b> The iPhone camera records visible color, puffing and charring; it cannot measure oven or pizza temperature. Continue measuring the stone using your IR heat gun. AI feedback is advisory, not an automatic cooking or food-safety verdict.</div>`;}

function experimentView(){
 const ex=state.data.experiments||[];const rows=state.labAnalytics||[];
 return head('Experiment lab','Unlimited recipes and variations. Link every pizza test to its recipe and dough batch.',`<button class="primary" data-new-experiment>+ New recipe experiment</button>`)+
 `<div class="notice-strip mb">Experiments clone a source recipe and its mixing steps. Edit the variation without altering your reference. Record batches and pizza evidence for each side before drawing conclusions.</div>`+
 panel('Recipe performance · observed values only',`<div style="overflow-x:auto"><table class="compact-table"><thead><tr><th>Recipe</th><th>Batches</th><th>Pizzas</th><th>Crisp /10</th><th>Rise /10</th><th>Bottom /10</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${num(r.batch_count)}</td><td>${num(r.pizza_count)}</td><td>${r.avg_crisp==null?'—':esc(r.avg_crisp)+' ('+num(r.crisp_count)+')'}</td><td>${r.avg_rise==null?'—':esc(r.avg_rise)+' ('+num(r.rise_count)+')'}</td><td>${r.avg_color==null?'—':esc(r.avg_color)}</td></tr>`).join('')||'<tr><td colspan="6">No recipes yet</td></tr>'}</tbody></table></div>`)+
 panel('Controlled experiments',ex.length?ex.map(x=>`<div class="data-card mb"><div class="between"><b>${esc(x.title)}</b><span class="pill">${esc(x.status)}</span></div><p class="small">${esc(x.source_name)} → ${esc(x.variation_name)} · ${esc(x.target_metric.replace('_',' '))}</p><p class="small muted">${esc(x.hypothesis||'No hypothesis recorded')}</p><div class="flex"><button class="sm" data-experiment-detail="${x.id}">Compare evidence</button><button class="sm" data-edit-recipe="${x.variation_recipe_id}">Edit variation</button><button class="sm" data-recipe-timeline="${x.variation_recipe_id}">Edit mixing steps</button><button class="sm" data-new-batch="${x.variation_recipe_id}">New test batch</button></div></div>`).join(''):'<p class="muted">Create your first experiment from any recipe.</p>')+
 (state.activeExperiment?panel('Experiment evidence',experimentReport(state.activeExperiment)):'');
}
function experimentReport(r){const a=r.comparison;return `<p class="small">${esc(r.guidance)}</p><div class="grid-2">${['source_recipe_id','variation_recipe_id'].map(k=>{let x=a[k],m=x.measurements;return `<div class="data-card"><b>${esc(x.recipe.name)}</b><p>Pizza tests: ${num(m.pizza_count)}</p><p>Crispness: ${m.avg_crisp==null?'Unmeasured':esc(m.avg_crisp)+'/10'} (${num(m.crisp_count)} ratings)</p><p>Rise: ${m.avg_rise==null?'Unmeasured':esc(m.avg_rise)+'/10'} (${num(m.rise_count)} ratings)</p><p>Bottom: ${m.avg_color==null?'Unmeasured':esc(m.avg_color)+'/10'} (${num(m.color_count)} ratings)</p><p>Batch count displayed: ${num(x.batches.length)} (latest 30)</p></div>`}).join('')}</div>`;}
function experimentForm(){return `<form id="experimentForm" class="stack"><label>Experiment title<input name="title" required maxlength="180" placeholder="Test lower honey for less scorching"></label><label>Starting recipe<select name="source_recipe_id" required>${selectRecipes('')}</select></label><label>Primary outcome<select name="target_metric">${[['crispness','Crispness'],['oven_spring','Oven spring'],['bottom_color','Bottom color'],['bake_time','Cook time']].map(x=>option(...x)).join('')}</select></label><label>Hypothesis / change to test<textarea name="hypothesis" rows="3" maxlength="4000" placeholder="Hypothesis and why. Edit ingredient amounts in the generated variation."></textarea></label><button class="primary">Create linked variation & experiment</button></form>`;}
async function loadExperiments(){let j=await api('labAnalytics');state.labAnalytics=j.analytics;navigate('experiments');}

function recipesView(){return head('Recipe library','Build, compare, and iterate dough formulas without overwriting the original.',`<button class="primary" data-edit-recipe="new">+ Create new recipe</button>`)+`<div class="grid-2">${state.data.recipes.map(r=>`<div class="data-card"><div class="between"><b>${esc(r.name)}</b><span class="pill ${r.status==='experimental'?'amber':'green'}">${esc(r.status)}</span></div><p class="muted small" style="margin:0">${esc(r.flour_name||'Flour not provided')}</p>${metrics(r)}<p class="small" style="margin:0">${esc(r.process_notes||r.notes||'No process details entered.')}</p><div class="flex"><button data-edit-recipe="${r.id}" class="sm">Edit formula</button><button data-recipe-timeline="${r.id}" class="sm">Edit steps / timeline (${stepsFor(r.id).length})</button><button data-clone="${r.id}" class="sm">Duplicate variation</button><button data-new-batch="${r.id}" class="sm">New batch →</button><button data-go="evidence" class="sm">Test →</button></div></div>`).join('')}</div>`;}
function recipeForm(r={}){let v=x=>r[x]??'';return `<form id="recipeForm" class="stack"><input type="hidden" name="id" value="${esc(r.id||'')}"><input type="hidden" name="parent_id" value="${esc(r.parent_id||'')}">${field('name','Recipe name',v('name'),'text','required')}
<div class="two"><label>Status<select name="status">${['current','experimental','archived'].map(x=>option(x,x,v('status')||'experimental')).join('')}</select></label>${field('flour_name','Flour brand / type',v('flour_name'),'text')}</div><div class="three">${field('flour_g','Flour (g)',v('flour_g'),'number','step="0.01" min="0"')}${field('water_g','Water (g)',v('water_g'),'number','step="0.01" min="0"')}${field('salt_g','Salt (g)',v('salt_g'),'number','step="0.01" min="0"')}${field('oil_g','Oil (g)',v('oil_g'),'number','step="0.01" min="0"')}${field('honey_g','Honey / sugar (g)',v('honey_g'),'number','step="0.01" min="0"')}${field('yeast_g','Yeast (g)',v('yeast_g'),'number','step="0.01" min="0"')}</div><label>Yeast type<select name="yeast_type">${['fresh compressed','instant dry','active dry'].map(x=>option(x,x,v('yeast_type')||'fresh compressed')).join('')}</select></label><label>Process / fermentation<textarea name="process_notes">${esc(v('process_notes'))}</textarea></label><label>Recipe notes<textarea name="notes">${esc(v('notes'))}</textarea></label><div class="notice-strip">Fields may be left blank for incomplete formulas. Baker's percentages update after saving, using flour weight as 100%.</div><button class="primary">Save recipe →</button></form>`;}
function shortDate(s){return s?esc(String(s).replace('T',' ').slice(0,16)):'Not recorded';}
function dtInput(v){return v?String(v).slice(0,16).replace(' ','T'):'';}
function avgScore(x){return x==null?'—':Number(x).toFixed(1)+'/10';}
function stepTimeLabel(s){const mn=s.target_min_minutes,mx=s.target_max_minutes;if(mn==null&&mx==null)return 'Timing optional';if(mn!=null&&mx!=null&&+mn!==+mx)return num(mn)+'–'+num(mx)+' min';return num(mn??mx)+' min';}
function recipeProcessView(id){const r=recipe(id);if(!r)return '<p>Recipe not found.</p>';const steps=stepsFor(id);return `<div class="stack"><div class="notice-strip">You can add, edit, delete or reorder recipe steps here. Every new batch snapshots this plan; existing batch histories stay unchanged. The planned times are defaults — actual steps are recorded against each batch.</div><div class="flex"><button class="primary" data-new-step="${esc(id)}">+ Add recipe step</button><button class="sm" data-edit-recipe="${esc(id)}">Edit ingredients</button><button class="sm" data-new-batch="${esc(id)}">Create batch from this version →</button></div><div class="process-list">${steps.length?steps.map((s,i)=>`<article class="process-step"><div class="step-index">${i+1}</div><div class="step-body"><div class="between"><h3>${esc(s.title)}</h3><span class="pill">${esc(s.stage.replaceAll('_',' '))}</span></div><p class="small muted">${esc(s.instructions||'No instructions added yet.')}</p><div class="recipe-metrics"><span>Duration <strong>${stepTimeLabel(s)}</strong></span>${s.target_start_min==null?'':`<span>Start <strong>+${num(s.target_start_min)} min</strong></span>`}</div><div class="flex mt"><button class="sm" data-edit-step="${esc(id)}:${esc(s.step_key)}">Edit step</button><button class="sm" data-step-move="${esc(id)}:${esc(s.step_key)}:up" ${i===0?'disabled':''} aria-label="Move ${esc(s.title)} earlier">↑ Earlier</button><button class="sm" data-step-move="${esc(id)}:${esc(s.step_key)}:down" ${i===steps.length-1?'disabled':''} aria-label="Move ${esc(s.title)} later">↓ Later</button></div></div></article>`).join(''):'<div class="empty">No process steps yet. Add the first step to begin your production timeline.</div>'}</div><button class="primary" data-new-step="${esc(id)}">+ Add another step</button></div>`;}
function recipeProcessPage(){const r=recipe(state.processRecipeId);if(!r)return head('Recipe process not found','Choose a recipe from the library.',`<button data-go="recipes">← Recipes</button>`);return head('Recipe step editor',`${esc(r.name)} · ${stepsFor(r.id).length} steps · Edit production instructions and planned timings.`,`<button data-go="recipes">← Recipe library</button>`)+`<div class="process-summary">${metrics(r)}<p class="small">Changes affect future batches only. Start times are measured from the beginning of the mix unless a later step explicitly states otherwise.</p></div>`+recipeProcessView(r.id);}
function recipeStepForm(id,s={}){const v=k=>s[k]??'';return `<form id="recipeStepForm" class="stack"><input name="recipe_id" type="hidden" value="${esc(id)}"><input name="step_key" type="hidden" value="${esc(v('step_key'))}"><div class="two">${field('title','Step title',v('title'),'text','required maxlength="160"')}<label>Stage<select name="stage">${['mix','rest','cold_bulk','ball','cold_ball','bake','other'].map(k=>option(k,k,v('stage')||'mix')).join('')}</select></label></div><div class="two">${field('sort_order','Order',v('sort_order')||((stepsFor(id).length+1)*10),'number','required min="0" max="10000" step="1"')}${field('target_start_min','Target start from beginning of mix (minutes, optional)',v('target_start_min'),'number','step=".1" min="0"')}</div><div class="two">${field('target_min_minutes','Target duration minimum (minutes)',v('target_min_minutes'),'number','step=".1" min="0"')}${field('target_max_minutes','Target duration maximum (minutes)',v('target_max_minutes'),'number','step=".1" min="0"')}</div><label>Instructions<textarea name="instructions" rows="4">${esc(v('instructions'))}</textarea></label><div class="notice-strip">Your batches retain the process template that existed when they were created. Actual times and quantities are entered separately per batch.</div><button class="primary">Save process step</button>${s.step_key?`<button type="button" class="danger-button" data-delete-step="${esc(id)}:${esc(s.step_key)}">Delete this step from future batches</button>`:''}</form>`;}
function batchStepForm(b,s){const x=(b.step_logs||[]).find(x=>x.step_key===s.step_key)||{};const v=k=>x[k]??'';return `<form id="batchStepForm" class="stack"><input type="hidden" name="batch_id" value="${esc(b.id)}"><input type="hidden" name="step_key" value="${esc(s.step_key)}"><p class="muted small">${esc(s.instructions||'')} · Target: ${s.target_min_minutes==null?'not specified':num(s.target_min_minutes)+(s.target_max_minutes!=null&&+s.target_max_minutes!==+s.target_min_minutes?'–'+num(s.target_max_minutes):'')+' min'}.</p><div class="two">${field('started_at','Actual started at',dtInput(v('started_at')),'datetime-local')}${field('finished_at','Actual finished at',dtInput(v('finished_at')),'datetime-local')}</div><div class="two">${field('actual_amount_g','Actual amount (g) if applicable',v('actual_amount_g'),'number','min="0" step=".1"')}${field('actual_temp_f','Measured dough °F (optional)',v('actual_temp_f'),'number','min="-30" max="150" step=".1"')}</div><label>Notes / deviations<textarea name="notes">${esc(v('notes'))}</textarea></label><button class="primary">Save actual step evidence</button></form>`;}
function containerForm(b){return `<form id="containerForm" class="stack"><input type="hidden" name="batch_id" value="${esc(b.id)}"><p class="small muted">Generate a separate handwritten label for each proofing container; a temperature can be logged for each mass.</p><div class="two">${field('label','Container label (e.g. Left bin)','', 'text')}${field('split_at','Split time (blank = now)','', 'datetime-local')}</div><div class="two">${field('mass_g','Actual dough mass (g)', '', 'number','min="0" step=".1"')}${field('temperature_f','Center dough temperature (°F)', '', 'number','min="-30" max="150" step=".1"')}</div><label>Notes<textarea name="notes"></textarea></label><button class="primary">Add container</button></form>`;}
function tempForm(b){return `<form id="batchTempForm" class="stack"><input type="hidden" name="batch_id" value="${esc(b.id)}"><div class="two"><label>Dough mass / container<select name="container_id">${option('','Whole batch / no container',null)}${(b.containers||[]).map(c=>option(c.id,c.container_code+' · '+(c.label||'container'),null)).join('')}</select></label>${field('temperature_f','Measured dough temperature °F','','number','required min="-30" max="150" step=".1"')}</div>${field('measured_at','Measured at (blank = now)','','datetime-local')}<label>Notes<textarea name="notes" placeholder="Day 1 center temp, fridge conditions, dough appearance…"></textarea></label><button class="primary">Save temperature reading</button></form>`;}
function usageForm(b){return `<form id="batchUsageForm" class="stack"><input type="hidden" name="batch_id" value="${esc(b.id)}"><div class="two"><label>Action<select name="event_type">${option('balled','Portioned / balled','balled')}${option('used','Used for pizzas','balled')}</select></label>${field('occurred_at','Time (blank = now)','','datetime-local')}</div><div class="two">${field('portions_count','Dough balls / pizzas (optional)','','number','min="1" step="1"')}${field('weight_g','Total dough weight (g) (optional)','','number','min="0" step=".1"')}</div><label>Notes<textarea name="notes" placeholder="220g balls / 160g balls, service day…"></textarea></label><button class="primary">Log batch use</button></form>`;}
function wasteForm(b){return `<form id="batchWasteForm" class="stack"><input type="hidden" name="batch_id" value="${esc(b.id)}"><div class="two"><label>Container<select name="container_id">${option('','Unassigned',null)}${(b.containers||[]).map(c=>option(c.id,c.container_code+' · '+(c.label||'container'),null)).join('')}</select></label>${field('occurred_at','Discarded at (blank = now)','','datetime-local')}</div><div class="two">${field('weight_g','Discarded weight (g)','','number','required min=".01" step=".01"')}<label>Reason<select name="reason">${['Overproofed','Too sticky','Damaged','Unused at end of service','Handling / trimming','Other'].map(r=>option(r,r)).join('')}</select></label></div><label>Notes<textarea name="notes"></textarea></label><button class="primary">Record waste</button></form>`;}
function actualMinutes(log){if(!log?.started_at||!log?.finished_at)return '—';const a=Date.parse(log.started_at.replace(' ','T')),b=Date.parse(log.finished_at.replace(' ','T'));return Number.isFinite(b-a)&&b>=a?(Math.round((b-a)/6000)/10)+' min':'—';}
function batchProductionView(b){const p=b.process_analytics||{}, t=p.temperature||{},w=p.waste||{};const plan=b.planned_steps||[],logs=b.step_logs||[];return `<div class="grid-2 mt"><div class="stack">${panel('Production step-by-step tracker',`<p class="small muted">Planned durations are frozen when this batch was created. Actual dates, times, quantities, temperatures and changes are recorded separately.</p>${plan.length?`<div class="quick-list">${plan.map((s,i)=>{const log=logs.find(x=>x.step_key===s.step_key);return `<button data-batch-step="${esc(s.step_key)}"><span><b>${i+1}. ${esc(s.title)} ${log?'✓':''}</b><small style="display:block">${esc(s.stage)} · target ${s.target_min_minutes==null?'not recorded':num(s.target_min_minutes)+(s.target_max_minutes!=null&&+s.target_max_minutes!==+s.target_min_minutes?'–'+num(s.target_max_minutes):'')+' min'} · actual ${actualMinutes(log)}</small><small style="display:block">${log?esc(log.notes||'Actuals saved · tap to edit'):esc(s.instructions||'Tap to log actual step')}</small></span>→</button>`;}).join('')}</div>`:'<p class="warning">This older batch has no saved process-plan snapshot. No steps are being inferred retroactively; create a new batch to use the new timeline.</p>'}`)}${panel('Split containers',`<div class="flex"><button data-container-add="${b.id}" class="sm">+ Add split container</button><button data-temp-add="${b.id}" class="sm">+ Log dough temperature</button></div><div class="quick-list mt">${(b.containers||[]).map(c=>`<div class="log-row"><b class="batch-code">${esc(c.container_code)}</b> ${esc(c.label||'')} · ${num(c.mass_g)} g · ${c.temperature_f==null?'No starting temperature':num(c.temperature_f)+'°F'} · ${shortDate(c.split_at)}</div>`).join('')||'<p class="muted small">No individual containers yet.</p>'}</div>`)}</div><div class="stack">${panel('Temperature, use & waste',`<div class="recipe-metrics"><span>Recorded temps <strong>${num(t.readings||0)}</strong></span><span>Min / max <strong>${num(t.min_temp_f)} / ${num(t.max_temp_f)}°F</strong></span><span>Used <strong>${num(p.used?.weight_g)} g</strong></span><span>Wasted <strong>${num(w.total_g)} g</strong></span><span>Waste entries <strong>${num(w.records||0)}</strong></span></div><p class="muted small">Recorded waste share (waste ÷ logged used + waste): ${p.logged_waste_share_percent==null?'—':num(p.logged_waste_share_percent)+'%'}; not total production yield unless usage is fully logged.</p><div class="flex"><button class="sm" data-usage-add="${b.id}">+ Balling / use</button><button class="sm" data-waste-add="${b.id}">+ Record waste</button></div>`)}${panel('Daily proofing temperatures',`<div class="quick-list">${(b.temperatures||[]).map(t=>{const c=(b.containers||[]).find(c=>+c.id===+t.container_id);return `<div class="log-row"><time>${shortDate(t.measured_at)}</time><b>${num(t.temperature_f)}°F</b> · ${esc(c?.container_code||'Whole batch')} ${esc(t.notes||'')}</div>`;}).join('')||'<p class="muted small">No daily temperature readings yet.</p>'}</div>`)}${panel('Usage & waste history',`<div class="quick-list">${(b.usage||[]).map(x=>`<div class="log-row"><time>${shortDate(x.occurred_at)}</time><b>${esc(x.event_type)}</b> · ${num(x.portions_count)} portions · ${num(x.weight_g)} g ${esc(x.notes||'')}</div>`).join('')}${(b.waste||[]).map(x=>`<div class="log-row"><time>${shortDate(x.occurred_at)}</time><b>Waste</b> · ${num(x.weight_g)} g · ${esc(x.reason)} ${esc(x.notes||'')}</div>`).join('')||'<p class="muted small">No waste logged yet.</p>'}</div>`)}</div></div>`;}

function batchForm(b={}){const v=k=>b[k]??'';return `<form id="batchForm" class="stack"><input type="hidden" name="id" value="${esc(v('id'))}"><div class="notice-strip">Each batch requires one recipe or variation. The code is generated automatically; write it on tape. For two bins from one mix, label them CODE 1/2 and CODE 2/2. A snapshot protects the original ingredient amounts.</div>
<label>Recipe / variation <select name="recipe_id" required>${option('','Select recipe',v('recipe_id'))}${selectRecipes(v('recipe_id'))}</select></label>
<label>Made by (chef who mixed the dough)<select name="made_by_user_id" ${b.id?'':'required'}>${b.id&&!v('made_by_user_id')?option('','Not recorded (older batch)',''):''}${batchMakerOptions(b.id?v('made_by_user_id'):(typeof window==='undefined'?'':window.PIZZA_LAB.user_id))}</select></label>
<p class="small muted">Defaults to your login. Choose another team member if you are entering a batch that they made. The app separately records who created the batch entry.</p>
${b.batch_code?`<div class="batch-code">${esc(b.batch_code)}</div>`:''}
<div class="two">${field('label','Batch nickname (optional)',v('label'),'text','placeholder="Monday AM mix"')}<label>Stage<select name="stage">${['bulk','balled','ready','used','archived'].map(x=>option(x,x,v('stage')||'bulk')).join('')}</select></label></div>
<div class="two">${field('mixed_at','Mixed at (optional)',dtInput(v('mixed_at')),'datetime-local')}${field('balled_at','Balled at (optional)',dtInput(v('balled_at')),'datetime-local')}</div>
<div class="three">${field('dough_temp_f','Finished dough °F',v('dough_temp_f'),'number','min="-20" max="150" step=".1"')}${field('fridge_temp_f','Fridge °F',v('fridge_temp_f'),'number','min="-20" max="100" step=".1"')}${field('container_count','Containers',v('container_count'),'number','min="1" max="100" step="1"')}</div>
<label>Mix / handling notes<textarea name="notes" rows="3" placeholder="e.g. cold water, two shallow tubs, mixer time…">${esc(v('notes'))}</textarea></label><button class="primary">${b.id?'Update batch':'Create batch + generate code'} →</button></form>`;}
function batchEventForm(b){return `<form id="batchEventForm" class="stack"><input type="hidden" name="batch_id" value="${esc(b.id)}"><p class="muted">Log a real event for <b>${esc(b.batch_code)}</b>. All measurements are optional.</p><div class="two"><label>Event<select name="phase">${['refrigerated','balled','ready','used','temperature','note','mixed'].map(x=>option(x,x)).join('')}</select></label>${field('occurred_at','When (blank = now)','','datetime-local')}</div>${field('temperature_f','Measured temperature °F (optional)','','number','min="-20" max="150" step=".1"')}<label>Notes<textarea name="note" rows="3" placeholder="Center temperature, handling, rise, fridge condition…"></textarea></label><button class="primary">Save batch event</button></form>`;}
function syncEvidenceRecipe(){const choice=$('#evidenceBatch'),r=$('#evidenceRecipe');if(!choice||!r)return;const b=batch(choice.value);if(b){r.value=String(b.recipe_id);r.disabled=true;}else{r.disabled=false;}}
function batchesView(){const batches=state.data.batches||[];const recipes=state.data.recipes;const value=state.batchFilter;const byRecipe=value==='all'?batches:batches.filter(b=>String(b.recipe_id)===value);const items=byRecipe.filter(b=>state.batchMakerFilter==='all'||(state.batchMakerFilter==='unknown'?b.made_by_user_id==null:String(b.made_by_user_id)===state.batchMakerFilter));
return head('Dough batch tracker','One permanent, hand-written code per mix. Select a recipe, label the bins, and link every pizza to its dough batch.',`<button data-new-batch="" class="primary">+ Create dough batch</button>`)+
`<div class="panel mb"><div class="two"><label>Filter by recipe<select id="batchFilterSelect"><option value="all">All recipes and variations</option>${recipes.map(r=>option(r.id,r.name,value)).join('')}</select></label><label>Made by<select id="batchMakerFilterSelect">${option('all','All team members',state.batchMakerFilter)}${(state.data.batch_makers||[]).map(u=>option(u.id,u.display_name+(+u.is_active?'':' (inactive)'),state.batchMakerFilter)).join('')}${option('unknown','Not recorded (older batches)',state.batchMakerFilter)}</select></label></div><p class="small muted">${batches.length} batches total · ${items.length} displayed. Tap a batch for proofing timeline and pizza-test analytics.</p></div><div class="grid-3">${items.map(b=>`<div class="data-card stack"><div class="between"><b class="batch-code">${esc(b.batch_code)}</b><span class="pill ${b.stage==='archived'?'':'green'}">${esc(b.stage)}</span></div><b>${esc(b.label||'Untitled batch')}</b><p class="small muted" style="margin:0">Recipe: ${esc(b.recipe_name)}<br>Made by: ${esc(makerLabel(b))}</p><div class="recipe-metrics"><span>Pizzas <strong>${num(b.pizza_tests||0)}</strong></span><span>Crispness <strong>${avgScore(b.avg_crisp)}</strong></span><span>Rise <strong>${avgScore(b.avg_rise)}</strong></span></div><p class="small" style="margin:0">Mixed: ${shortDate(b.mixed_at)}<br>Balled: ${shortDate(b.balled_at)}</p><div class="flex"><button class="sm" data-batch-detail="${b.id}">View analytics →</button><button class="sm" data-copy-batch="${esc(b.batch_code)}">Copy code</button></div><button class="sm" data-batch-evidence="${b.id}">+ Record pizza from this batch</button></div>`).join('')||'<div class="empty">No batches found. Create your first batch and choose its recipe.</div>'}</div>`;}
async function loadBatchDetail(id){const res=await fetch('api.php?action=batchDetail&id='+encodeURIComponent(id),{credentials:'same-origin'});const j=await res.json();if(!res.ok||!j.ok)throw Error(j.error||'Unable to load batch');state.activeBatch=j.batch;navigate('batchDetail');}
function batchDetailView(){const b=state.activeBatch;if(!b)return '<p>Select a dough batch.</p>';const a=b.analytics||{};const snap=b.recipe_at_mixing||{};return head('Batch '+esc(b.batch_code),`Recipe: ${esc(snap.name||b.recipe_name||'Unknown')} · ${esc(b.stage)} · ${esc(b.label||'')}`,`<button data-batch-evidence="${b.id}" class="primary">+ Test pizza from batch →</button>`)+
`<div class="panel mb"><div class="between"><div><p class="overline">WRITE ON TAPE</p><div class="batch-code large">${esc(b.batch_code)}</div><p class="small muted">${esc(snap.name||b.recipe_name||'')}<br>Made by: ${esc(makerLabel(b))}<br>Recorded by: ${esc(b.recorded_by_name||'Not recorded')}</p></div><div class="stack"><button data-copy-batch="${esc(b.batch_code)}" class="sm">Copy batch code</button><button data-edit-batch="${b.id}" class="sm">Edit batch</button><a class="sm" href="agent_chat.php?scope=batch&id=${encodeURIComponent(b.id)}">Ask agent about batch ↗</a><button data-export-batch="${b.id}" class="sm">Export complete report (.json)</button><button data-batch-event="${b.id}" class="sm">Log fermentation event</button></div></div></div>
<div class="grid-4 mb"><div class="metric"><small>PIZZAS TESTED</small><strong>${num(a.pizzas||0)}</strong></div><div class="metric"><small>AVG CRISPNESS</small><strong>${avgScore(a.avg_crisp)}</strong><div class="foot">${num(a.crisp_count||0)} rated</div></div><div class="metric"><small>AVG RISE</small><strong>${avgScore(a.avg_rise)}</strong><div class="foot">${num(a.rise_count||0)} rated</div></div><div class="metric"><small>AVG BOTTOM COLOR</small><strong>${avgScore(a.avg_color)}</strong><div class="foot">${num(a.color_count||0)} rated</div></div></div>
<div class="grid-2"><div class="stack">${panel('Recipe at batch creation',`${metrics(snap)}<p class="small">${esc(snap.flour_name||'Flour unrecorded')} · ${esc(snap.yeast_type||'Yeast unrecorded')}</p><p class="small muted">Recipe data was frozen when this batch was created, even if the recipe is edited later.</p>`) }${panel('Fermentation and temperature',`<div class="recipe-metrics"><span>Mixed <strong>${shortDate(b.mixed_at)}</strong></span><span>Balled <strong>${shortDate(b.balled_at)}</strong></span><span>Dough temp <strong>${num(b.dough_temp_f)}°F</strong></span><span>Fridge <strong>${num(b.fridge_temp_f)}°F</strong></span><span>Bins <strong>${num(b.container_count)}</strong></span></div><p class="small">${esc(b.notes||'No notes recorded.')}</p><div class="mt"><button class="sm" data-batch-event="${b.id}">+ Log batch event</button></div>${b.events.length?`<div class="quick-list mt">${b.events.map(x=>`<div class="log-row"><time>${esc(x.occurred_at)}</time><b>${esc(x.phase)}</b> ${x.temperature_f==null?'':num(x.temperature_f)+'°F'} ${esc(x.note)}</div>`).join('')}</div>`:'<p class="muted small mt">No fermentation events logged yet.</p>'}`)}</div><div class="stack">${panel('Measured batch analytics',`<div class="recipe-metrics"><span>Avg bake <strong>${a.avg_bake_s==null?'—':(Number(a.avg_bake_s)/60).toFixed(2)+' min'}</strong></span><span>Avg stone <strong>${num(a.avg_stone_f)}°F</strong></span><span>Avg sauce <strong>${num(a.avg_sauce_g)} g</strong></span><span>Avg cheese <strong>${num(a.avg_cheese_g)} g</strong></span><span>Avg dough age <strong>${num(a.avg_dough_age_h)} h</strong></span></div><p class="small muted">Blank observations do not count toward averages. Scores are chef ratings (1–10); correlations do not prove a cause.</p>`)}${panel('Pizzas from this batch',b.pizzas.length?`<div class="quick-list">${b.pizzas.map(e=>`<button data-detail="${e.id}"><span><b>${esc(e.label)}</b><small style="display:block">${shortDate(e.created_at)} · ${num(e.stone_start_f)}°F · ${num(e.sauce_g)}g sauce · ${e.bake_seconds==null?'—':(Number(e.bake_seconds)/60).toFixed(1)+' min'}</small></span>→</button>`).join('')}</div>`:'<p class="muted small">No pizza tests attached yet. Create evidence and select this batch.</p>')}</div></div>`+batchProductionView(b);}
function evidenceView(){let evs=state.data.evidence;return head('Pizza evidence','One record per baked pizza. Log your real stone readings, bake conditions, photos and notes.',`<button class="primary" data-new-evidence="1">+ Record pizza test</button>`)+`<div class="grid-3">${evs.map(e=>`<button class="data-card" style="text-align:left" data-detail="${e.id}"><div class="between"><b>${esc(e.label)}</b><span class="pill">#${e.id}</span></div><div class="small">${e.batch_code?`<b>${esc(e.batch_code)}</b> · `:''}${esc(e.recipe_name||'Recipe not assigned')}</div><div class="recipe-metrics"><span>Stone <strong>${e.stone_start_f==null?'—':num(e.stone_start_f)+'°F'}</strong></span><span>Time <strong>${e.bake_seconds==null?'—':Math.round(+e.bake_seconds/60*10)/10+'m'}</strong></span><span>Load <strong>${e.oven_load==null?'—':(+e.oven_load<35?'Low':+e.oven_load<70?'Moderate':'High')}</strong></span></div><div class="small">${esc((e.created_at||'').slice(0,16))} →</div></button>`).join('')||'<div class="empty">No evidence recorded yet.</div>'}</div>`;}
function evidenceForm(e={}){
 let v=x=>e[x]??'';
 const moisture=Number(v('cheese_moisture'))||0;
 const load=v('oven_load');
 return `<form id="evidenceForm" class="stack"><input type="hidden" name="id" value="${esc(e.id||'')}">
 <p class="muted small">Only the test record itself is required. Every measurement below may be left blank; the agent will say when evidence is missing.</p>
 <div class="two"><label>Dough batch (optional)<select id="evidenceBatch" name="batch_id">${option('','No batch selected',v('batch_id')||state.pendingBatchId)}${selectBatches(v('batch_id')||state.pendingBatchId,true)}</select></label><label>Recipe (auto-selected from batch)<select id="evidenceRecipe" name="recipe_id">${option('','Not assigned',v('recipe_id')||batch(v('batch_id')||state.pendingBatchId)?.recipe_id||'')}${selectRecipes(v('recipe_id')||batch(v('batch_id')||state.pendingBatchId)?.recipe_id||'')}</select></label></div><div class="two">${field('label','Test label (optional)',v('label'),'text','placeholder="Automatically named if empty"')}<div class="notice-strip">Select a batch to automatically attach the correct recipe. Individual pizza measurements remain optional.</div></div>
 <div class="three">${field('pizza_size_in','Pizza size (inches)',v('pizza_size_in'),'number','min="3" max="30" step=".1"')}${field('dough_ball_g','Dough ball (g)',v('dough_ball_g'),'number','min="10" step=".1"')}${field('dough_age_h','Dough age (hours)',v('dough_age_h'),'number','min="0" step=".5"')}</div>
 <div class="two">${field('sauce_g','Sauce weight (g)',v('sauce_g'),'number','min="0" step=".1"')}${field('cheese_g','Cheese weight (g)',v('cheese_g'),'number','min="0" step=".1"')}</div>
 <label>Cheese moisture rating (optional)</label><div class="moisture-scale"><button type="button" class="${moisture===0?'selected':''}" data-moisture="">Not recorded</button>${Array.from({length:10},(_,i)=>`<button type="button" data-moisture="${i+1}" class="${moisture===i+1?'selected':''}" title="Cheese moisture ${i+1} out of 10">${i+1}</button>`).join('')}</div><input type="hidden" name="cheese_moisture" id="cheeseMoisture" value="${esc(v('cheese_moisture'))}"><div class="range-labels"><span>1 · Very dry</span><span>5 · Moderate</span><span>10 · Very wet</span></div>
 <div class="three">${['rim_rise_score','crispness_score','bottom_color_score'].map((key,i)=>`<label>${['Rim rise score (1–10)','Crispness score (1–10)','Bottom color score (1–10)'][i]}<select name="${key}">${option('','Not rated',v(key))}${Array.from({length:10},(_,j)=>option(j+1,j+1,v(key))).join('')}</select></label>`).join('')}</div>
 <div class="three">${field('stone_start_f','Launch stone °F (IR gun)',v('stone_start_f'),'number','min="0" max="1500" step=".1"')}${field('stone_finish_f','Finish stone °F (IR gun)',v('stone_finish_f'),'number','min="0" max="1500" step=".1"')}${field('bake_seconds','Cook time (seconds)',v('bake_seconds'),'number','min="10" max="3600"')}</div>
 <label class="flex"><input type="checkbox" id="recordOvenLoad" ${load!==''?'checked':''} style="width:18px;min-height:18px"> Record oven use (optional)</label><div id="loadControl" ${load===''?'hidden':''}><label>Oven activity: <output id="loadLabel">${esc(load===''?50:load)}</output>/100<input name="oven_load" id="ovenLoad" type="range" min="0" max="100" value="${esc(load===''?50:load)}" ${load===''?'disabled':''}><div class="range-labels"><span>Low use</span><span>Moderate</span><span>High use</span></div></label></div>
 <label>Notes / observations (optional)<textarea name="notes" rows="4" placeholder="Oven spring, rim color, bottom crispness, sauce, tip flop…">${esc(v('notes'))}</textarea></label>
 <button class="primary">${e.id?'Save changes':'Create pizza evidence'} →</button></form>`;
}
function mediaHtml(items){const imgs=items.filter(x=>x.kind!=='audio'&&x.kind!=='scan');const audio=items.filter(x=>x.kind==='audio');return `<div class="media-grid">${imgs.map(x=>`<div class="media-tile"><a href="media.php?id=${x.id}" target="_blank" rel="noopener"><img loading="lazy" src="media.php?id=${x.id}" alt="${esc(x.kind)} pizza evidence"></a><div>${esc(x.kind)} · ${esc(x.created_at)}</div></div>`).join('')}${audio.map(x=>`<div class="media-tile"><audio controls preload="none" src="media.php?id=${x.id}"></audio><div>Voice note · ${esc(x.created_at)}</div></div>`).join('')}</div>`;}
function readingsTable(readings){if(!readings.length)return '<p class="muted small">No heat-gun readings logged yet.</p>';
const ordered=[...readings].sort((a,b)=>+a.elapsed_seconds-+b.elapsed_seconds);const launch=ordered.find(x=>x.phase==='launch');
let report='Recovery time cannot be calculated yet. Measure the launch area, its post-bake drop and a subsequent return to within 10°F of launch temperature.';
if(launch){const drop=ordered.find(x=>+x.elapsed_seconds>+launch.elapsed_seconds && +x.stone_f < +launch.stone_f-10);
if(drop){const recovered=ordered.find(x=>+x.elapsed_seconds>+drop.elapsed_seconds&&+x.stone_f>=+launch.stone_f-10);
if(recovered)report=`Measured recovery: ${Math.round((recovered.elapsed_seconds-drop.elapsed_seconds)/60*10)/10} minutes from first recorded low reading (${num(drop.stone_f)}°F) to within 10°F of launch (${num(launch.stone_f)}°F). Actual recovery may be faster.`;
else report=`Stone dropped to ${num(drop.stone_f)}°F. Awaiting a subsequent reading at ${num(+launch.stone_f-10)}°F or above.`;
}else report='No stone drop of more than 10°F recorded at the launch position; recovery not measurable yet.';}
return `<p class="small">${report}</p><table class="compact-table"><thead><tr><th>Phase</th><th>°F</th><th>Seconds since launch</th></tr></thead><tbody>${ordered.map(r=>`<tr><td>${esc(r.phase)}</td><td>${num(r.stone_f)}</td><td>${num(r.elapsed_seconds)}s</td></tr>`).join('')}</tbody></table>`;}
function obsHtml(items){return items.length?items.map(x=>{let y;try{y=JSON.parse(x.text)}catch{y={summary:x.text}}return `<div class="result-box"><div class="between"><b>${x.kind==='live'?'Live scan':'Evidence analysis'}</b><span class="small">${esc(x.created_at)}</span></div>${formatAnalysis(y)}</div>`;}).join(''):'<p class="muted">No analysis yet. Upload photos and select Analyze.</p>';}
function formatAnalysis(a){const lists=(xs)=>Array.isArray(xs)&&xs.length?`<ul>${xs.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:'';return `<p>${esc(a.summary||'No summary')}</p><span class="pill">Confidence: ${esc(a.confidence||'unrated')}</span>${lists(a.visual_findings)}${a.suggestions?.length?'<p class="tiny accent">SUGGESTIONS</p>':''}${lists(a.suggestions)}${a.warning?`<div class="warning mt">${esc(a.warning)}</div>`:''}<p class="small">AI visual estimate only. Verify with real observations and your IR heat gun.</p>`;}
async function detailView(id){try{const j=await fetch('api.php?action=detail&id='+id,{credentials:'same-origin'}).then(r=>r.json());if(!j.ok)throw Error(j.error);state.detail=j.detail;state.activeEvidence=+id;selectTimer(state.activeEvidence);navigate('detail');}catch(e){toast(e.message,true);}}
function detailHtml(){let e=state.detail;if(!e)return '<p>No evidence selected.</p>';return head(`Test #${e.id}: ${esc(e.label)}`,`Recipe: ${esc(recipe(e.recipe_id)?.name||'Not assigned')} · ${esc(batch(e.batch_id)?.batch_code||'No batch')} · ${esc(e.created_at)}`,`<div class="flex"><button data-edit-evidence="${e.id}">Edit test</button><button class="primary" data-go="live">Open live scanner →</button></div>`)+`<div class="grid-2"><div class="stack">${panel('Measurements',`<div class="recipe-metrics"><span>Pizza <strong>${num(e.pizza_size_in)}" / ${num(e.dough_ball_g)}g</strong></span><span>Stone <strong>${num(e.stone_start_f)}°F</strong></span><span>Bake <strong>${e.bake_seconds==null?'—':Math.round(e.bake_seconds/6)/10+'min'}</strong></span><span>Load <strong>${e.oven_load==null?'—':num(e.oven_load)+'%'}</strong></span><span>Sauce <strong>${e.sauce_g==null?'—':num(e.sauce_g)+'g'}</strong></span><span>Cheese <strong>${e.cheese_g==null?'—':num(e.cheese_g)+'g'}</strong></span><span>Cheese moisture <strong>${e.cheese_moisture==null?'—':esc(e.cheese_moisture)+'/10'}</strong></span><span>Crisp <strong>${e.crispness_score==null?'—':esc(e.crispness_score)+'/10'}</strong></span><span>Rise <strong>${e.rim_rise_score==null?'—':esc(e.rim_rise_score)+'/10'}</strong></span></div><p class="muted">${esc(e.notes||'No written notes yet')}</p>`)}${panel('Temperature recovery',`<form id="readingForm" class="stack"><input type="hidden" name="evidence_id" value="${e.id}"><div class="three"><label>Reading type<select name="phase">${['launch','check','finish','recovery'].map(x=>option(x,x)).join('')}</select></label>${field('stone_f','Stone °F',e.stone_start_f,'number','required min="0" max="1500" step=".1"')}${field('elapsed_seconds','Seconds after launch',0,'number','min="0" max="7200"')}</div><button class="sm">Log IR reading</button></form><div class="mt">${readingsTable(e.readings)}</div>`)}${panel('Claude recommendations',`<button id="analyzeEvidence" class="primary sm">Analyze top / bottom photos</button><div class="stack mt">${obsHtml(e.observations)}</div>`)}</div><div class="stack">${panel('Evidence media',`${mediaHtml(e.media)}<p class="small">Photos: top, bottom, side. Camera snapshots and audio are stored privately.</p><div class="flex">${['top','bottom','side','audio'].map(k=>`<label class="sm" style="flex:1">${k.toUpperCase()}<input class="media-upload" type="file" data-kind="${k}" accept="${k==='audio'?'audio/*':'image/jpeg,image/png,image/webp,image/*'}" ${k==='audio'?'':'capture="environment"'}></label>`).join('')}</div>`)}${panel('Voice notes',`<p class="small">Record a field note about puffing, crispness, color or sauce. Review it before saving.</p><div class="flex"><button id="recordNote">● Record note</button><button id="stopNote" disabled>■ Stop</button><button id="saveNote" disabled class="primary">Save note</button></div><audio id="notePreview" style="width:100%;margin-top:10px" controls></audio>`)}${panel('Saved bake timeline', e.events?.length?e.events.map(x=>`<div class="log-row"><time>${esc(x.created_at)} (${fmt(x.elapsed_seconds)})</time>${esc(x.message)} ${x.event_source==='voice_command'?`<span class="pill green">Voice · ${esc(x.actor_profile||'Chef')}</span>`:x.event_source==='agent_alert'?'<span class="pill">Agent alert</span>':''}</div>`).join(''):'<p class="muted">No timer or oven events saved yet.</p>')}${panel('Quick timer',`<p class="small">An individual countdown is available for this pizza in the live scanner.</p><button data-go="live" class="primary">Open oven session</button>`)}</div></div>`;}
function liveView(){const testId=state.activeEvidence||(+state.data.evidence[0]?.id||0);if(!state.activeEvidence)state.activeEvidence=testId;selectTimer(testId);
return head('Live pizza scanner','Camera-guided tracking with timer cues and optional periodic Claude vision snapshots.',`<span class="pill amber">FOREGROUND SESSION ONLY</span>`)+
`<div class="notice-strip mb">The scanner interprets visible browning and rise from snapshots—not temperature, exact doneness, or food safety. Keep your phone safely away from the wood fire. Timers, camera and voice alerts need the page active; iOS may suspend them when locked or in the background.</div>
<div class="grid-2"><div class="stack">${panel('Camera · pizza view',`<div class="camera"><div id="cameraEmpty" class="camera-placeholder">◎<br>Camera is off<br><small>Tap Start camera and allow access</small></div><video id="liveVideo" playsinline muted autoplay style="display:none"></video><span class="camera-label">● LIVE · visual, not thermal</span></div><div class="camera-actions"><button id="startCamera" class="primary">Start camera</button><button id="stopCamera">Stop</button><button id="shotTop">Capture top</button><button id="shotBottom">Capture bottom</button></div><div class="flex mt"><button id="scanNow">◎ Analyze current frame</button><label class="flex"><input id="autoScan" type="checkbox" style="width:18px;min-height:18px" ${state.scanner?'checked':''}> Auto-scan every 30s</label></div><div id="scanResult" class="mt">${state.lastAnalysis?formatAnalysis(state.lastAnalysis):'<p class="muted small">Analysis appears here after you capture and scan. Charges may apply to each Claude API request.</p>'}</div>`)}${panel('Stone temperature & oven traffic',`<div class="two">${field('stoneReading','IR heat-gun reading °F','','number','min="0" max="1500" step=".1"')}<label>Reading type<select id="readingPhase">${['launch','check','finish','recovery'].map(x=>option(x,x)).join('')}</select></label></div><div class="flex mt"><button id="logReading" class="sm primary">Save temperature reading</button><button id="seeReadings" class="sm">View readings</button></div><div class="hint mt">The low-to-high oven-use meter is entered on each evidence record. A recovery time needs a launch reading and subsequent checks at the same stone location. No temperature is inferred from the camera.</div>`)}</div>
<div class="stack">${panel('Active pizza',`<label>Evidence record<select id="liveEvidence">${selectEvidence(testId)}</select></label><div class="timer-digits" id="timerDigits">08:00</div><div class="timer-track"><div id="timerProgress" style="width:0%"></div></div><div class="three">${field('timerDuration','Total bake (seconds)',state.timer.duration,'number','min="10" max="3600"')}${field('pullCue','Pull-back cue (seconds)',state.timer.pull||state.pull,'number','min="5" max="1800"')}${field('turnCue','Rotate reminder (every s)',state.timer.turn||state.turn,'number','min="10" max="1800"')}</div><div class="flex mt"><button id="startTimer" class="primary">▶ Start timer</button><button id="stopTimer">■ Stop timer</button><button id="pauseTimer">Pause</button><button id="resetTimer">Reset</button></div><div class="voice-controls mt"><div class="between"><b>Voice commands</b><span class="pill" id="micStatus">Microphone off</span></div><div class="flex mt"><button id="listenStart" class="sm primary">🎙 Enable voice commands</button><button id="listenStop" class="sm">Mute mic</button></div><p class="small" id="lastHeard">Say “Pizza, start timer” or “Pizza, stop timer.” “Pizza, rotate” and “Pizza, time left” are agent announcements, not user commands.</p></div><label class="flex mt"><input id="voiceToggle" type="checkbox" ${state.voice?'checked':''} style="width:18px;min-height:18px"> Speak alerts (requires audio permission)</label><div class="warning mt"><b>Important:</b> Pull-back and rotation cues are adjustable time reminders, not automatic detection of first puff. Move the pizza when your actual visual observation calls for it.</div>`)}${panel('Event timeline',`<div class="log" id="liveLog">${state.log.map(x=>`<div class="log-row"><time>${esc(x.time)}</time>${esc(x.message)}</div>`).join('')||'<p class="muted small">Start a timer to log events.</p>'}</div>`)}${panel('Quick finish',`<button id="finishPizza" class="primary">Finish & open evidence record →</button><p class="muted small">Upload separate top and bottom views for a documented final assessment.</p>`)}</div></div>`;
}
function profileSettings(){
 const v=state.data.voice_profile||{};
 const voices=window.speechSynthesis?.getVoices?.()||[];
 return `<form id="voiceProfileForm" class="stack">
 ${field('profile_name','Voice profile / chef name',v.profile_name||window.PIZZA_LAB.user,'text','maxlength="80" required')}
 <div class="two">${field('wake_phrase','Wake phrase',v.wake_phrase||'pizza','text','maxlength="40" required')}${field('start_alias','Optional start-timer alias',v.start_alias||'','text','placeholder="start bake" maxlength="70"')}</div>
 <label>Recognition language<select name="language">${['en-US','en-GB','en-AU'].map(x=>option(x,x,v.language||'en-US')).join('')}</select></label>
 <label>Spoken notification voice<select name="voice_uri">${option('','Device default',v.voice_uri||'')}${voices.map(x=>option(x.voiceURI,x.name+' · '+x.lang,v.voice_uri||'')).join('')}</select></label>
 <label>Speaking speed: <output id="rateLabel">${v.voice_rate||'0.95'}</output><input id="voiceRate" name="voice_rate" type="range" min="0.6" max="1.5" step="0.05" value="${esc(v.voice_rate||'0.95')}"></label>
 <label class="flex"><input name="require_wake" type="checkbox" style="width:18px;min-height:18px" ${v.require_wake===undefined||+v.require_wake?'checked':''}> Require wake phrase before timer commands</label>
 <button class="primary">Save voice profile</button></form>
 <p class="small">A voice profile identifies the selected chef in the event history. It is NOT voiceprint enrollment or speaker verification. iOS Safari may interrupt speech recognition; keep this page open and the mic enabled.</p>`;
}
function myPasswordForm(){return `<form id="myPasswordForm" class="stack"><label>Current password<input name="current_password" type="password" required autocomplete="current-password"></label><label>New password (12+ characters)<input name="new_password" type="password" required minlength="12" autocomplete="new-password"></label><button class="primary" type="submit">Change password</button></form>`;}
function teamView(){if(window.PIZZA_LAB.role!=='super_admin')return '<div class="danger">Access denied.</div>';
 const users=state.teamUsers||[];
 return head('Team members','Create team accounts with the same recipe, batch, pizza scanner, timer and Claude permissions, without Super Admin privileges.',`<button class="primary" data-add-team>+ Add team member</button>`)+
 `<div class="notice-strip mb">Only the Super Admin can manage accounts and change the shared Claude key/model. Disabling a member blocks subsequent authenticated requests. Team activity uses each member’s own login and voice profile.</div>`+
 `<div class="grid-2">${users.map(u=>`<div class="data-card"><div class="between"><b>${esc(u.display_name)}</b><span class="pill ${+u.is_active?'green':'amber'}">${u.role==='super_admin'?'Super Admin':(+u.is_active?'Active':'Disabled')}</span></div><p class="small muted">${esc(u.email)}</p><p class="small">${u.role==='super_admin'?'Account owner · cannot be edited here':'Team Member · recipes, batches, timers, evidence and agent'}</p>${u.role==='team_member'?`<div class="flex"><button class="sm" data-edit-team="${u.id}">Edit member</button><button class="sm" data-reset-team="${u.id}">Reset password</button></div>`:''}</div>`).join('')}</div>`;
}
function teamMemberForm(u={}){return `<form id="teamMemberForm" class="stack"><input type="hidden" name="id" value="${esc(u.id||'')}">${field('display_name','Display name',u.display_name||'','text','required maxlength="120"')}${field('email','Email / login',u.email||'','email','required maxlength="190"')}${u.id?`<label>Status<select name="is_active">${option(1,'Active',u.is_active)}${option(0,'Disabled',u.is_active)}</select></label>`:`${field('password','Initial password (12+ characters)','','password','required minlength="12" autocomplete="new-password"')}<p class="small">Share the initial password privately. The member can change it after signing in.</p>`}<p class="small">Role: Team Member. Super Admin privileges cannot be assigned through this form.</p><button class="primary" type="submit">${u.id?'Save team member':'Create team member'}</button></form>`;}
function teamResetForm(u){return `<form id="teamResetForm" class="stack"><input name="id" type="hidden" value="${esc(u.id)}"><p>Reset password for <b>${esc(u.display_name)}</b>. You will need to tell them their new password privately.</p>${field('password','New password (12+ characters)','','password','required minlength="12" autocomplete="new-password"')}<button class="primary" type="submit">Reset password</button></form>`;}
async function loadTeam(){if(window.PIZZA_LAB.role!=='super_admin')throw Error('Super Admin permissions required');const data=await api('teamUsers');state.teamUsers=data.users;navigate('team');}

function settingsView(){return head('AI, voice & settings','Manage your voice profile, password and Claude access.')+
`<div class="grid-2">${window.PIZZA_LAB.role==='super_admin'?panel('Claude vision',`<form id="settingsForm" class="stack"><label>Claude model ID<input name="model" value="${esc(state.data.settings.model||'claude-haiku-5-5')}" required></label><label>API key <small>(${state.data.settings.key_configured?'configured':'not configured'})</small><input name="api_key" type="password" autocomplete="off" placeholder="sk-ant-… (leave blank to keep existing)"></label><label class="flex"><input name="remove_key" type="checkbox" style="width:18px;min-height:18px"> Remove existing API key</label><button class="primary">Save settings</button></form><p class="small">Enter a valid model ID available on your Anthropic account. The browser never receives your saved key.</p>`):panel('Claude vision',`<p>Claude analysis is available with the shared model configured by your administrator. Team accounts cannot view or change API keys.</p>`)}${panel('Voice profile & spoken alerts',profileSettings())}${panel('Account password',myPasswordForm())}${panel('iPhone & privacy',`<p>Camera and microphone start only after your permission.</p><p>AI receives selected photos when you request analysis or enable auto-scan.</p><p>Voice recognition can be browser/cloud-assisted; avoid speaking private information during an active mic session.</p><p>Voice commands and reminders work only while the page is open and the browser permits audio. They cannot be guaranteed when locked.</p><p>The iPhone does not expose an oven temperature sensor to websites. Enter heat-gun readings manually.</p><div class="divider"></div><button id="soundTest">Test spoken reminder</button>`)}</div>`;
}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function navigate(page,rerender=true){if(state.page==='detail'&&page!=='detail'&&state.mediaRecorder?.state==='recording')state.mediaRecorder.stop();if(state.page==='live'&&page!=='live'){stopCamera();stopListening();}state.page=page;$$('#mainNav button').forEach(b=>b.classList.toggle('selected',b.dataset.page===page));$('#pageLabel').textContent=({overview:'Overview',recipes:'Recipes',batches:'Dough batches',batchDetail:'Batch analytics',evidence:'Pizza evidence',live:'Live scanner',settings:'Settings',team:'Team members',detail:'Evidence details',process:'Recipe steps',experiments:'Experiments'})[page];if(rerender)render();window.scrollTo({top:0,behavior:'instant'});$('.sidebar').classList.remove('open');}
function render(){let p=state.page;$('#view').innerHTML=({overview:overview,recipes:recipesView,batches:batchesView,batchDetail:batchDetailView,evidence:evidenceView,live:liveView,settings:settingsView,team:teamView,detail:detailHtml,process:recipeProcessPage,experiments:experimentView}[p]||overview)();if(p==='live'){updateTimerUI();updateMicStatus();}}
function formDataObj(el){let d={};for(const [k,v] of new FormData(el)){d[k]=v;}return d;}
async function execute(action,obj,success='Saved'){const out=await api(action,obj);toast(success);await refresh();return out;}
async function upload(file,kind,id=state.activeEvidence){if(!id)throw Error('Create/select an evidence record first.');let d=new FormData();d.append('evidence_id',id);d.append('kind',kind);d.append('file',file,file.name||`${kind}.jpg`);return api('upload',d);}
function saveTimers(){try{localStorage.setItem(timerStorageKey,JSON.stringify(state.timers));}catch{}}
function timerFor(id){id=String(id||0);if(!state.timers[id])state.timers[id]={running:false,start:0,elapsed:0,duration:480,cues:{},testId:+id};state.timers[id].cues=state.timers[id].cues||{};return state.timers[id];}
function selectTimer(id){state.timer=timerFor(id);saveTimers();}
function log(msg,id=state.activeEvidence,source='manual'){const x={time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}),message:msg,actor:source==='voice_command'?(state.data.voice_profile?.profile_name||window.PIZZA_LAB.user):'',source};state.log.unshift(x);state.log=state.log.slice(0,60);if(id)api('event',{evidence_id:id,elapsed_seconds:Math.min(7200,elapsed()),message:msg,event_source:source}).catch(()=>{});const el=$('#liveLog');if(el)el.innerHTML=state.log.map(x=>`<div class="log-row"><time>${esc(x.time)}</time>${esc(x.message)}${x.source==='voice_command'?` · ${esc(x.actor)}`:''}</div>`).join('');}
function speak(str){
 if(!state.voice)return;
 try{if('speechSynthesis'in window){
  state.speakingUntil=Date.now()+Math.max(2500,Math.min(10000,str.length*100));
  speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(str);
  u.rate=+(state.data.voice_profile?.voice_rate||.95);u.volume=1;
  const uri=state.data.voice_profile?.voice_uri;
  const v=speechSynthesis.getVoices().find(x=>x.voiceURI===uri);
  if(v)u.voice=v;
  speechSynthesis.speak(u);
 }}catch{}
}
function beep(){try{let a=new(window.AudioContext||window.webkitAudioContext)();let o=a.createOscillator(),g=a.createGain();o.frequency.value=660;g.gain.setValueAtTime(.09,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.25);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.25);setTimeout(()=>a.close(),350);}catch{}}
function notify(message,force=false,id=state.activeEvidence){log(message,id,'agent_alert');toast(message,true);beep();if(force||state.voice)speak(message);}
function elapsed(){return state.timer.running?state.timer.elapsed+Math.max(0,Math.floor((Date.now()-state.timer.start)/1000)):state.timer.elapsed;}
function fmt(s){s=Math.max(0,Math.round(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function updateTimerUI(){for(const [id,timer] of Object.entries(state.timers)){if(timer.running && +id!==+state.activeEvidence){checkTimer(timer,+id);}}const t=state.timer;const e=elapsed();const v=$('#timerDigits'),p=$('#timerProgress');if(v)v.textContent=fmt(Math.max(0,t.duration-e));if(p)p.style.width=Math.min(100,e/t.duration*100)+'%';if(!t.running)return;
if(e>=(t.pull||state.pull)&&!t.cues.pull){t.cues.pull=true;notify('Pizza, check the initial puff. Pull back when the rim has expanded.');saveTimers();}
if(e>=(t.turn||state.turn)&&(t.turn||state.turn)>0){let slot=Math.floor(e/(t.turn||state.turn));if(slot>0&&!t.cues['turn'+slot]){t.cues['turn'+slot]=true;notify('Pizza, rotate if needed. Check the fire-facing rim.');saveTimers();}}
if(e>=Math.floor(t.duration/2)&&!t.cues.halfway&&e<t.duration){t.cues.halfway=true;notify('Pizza, time left: '+fmt(t.duration-e)+'.');saveTimers();}
if(t.duration-e<=60&&t.duration-e>0&&!t.cues.lastMinute){t.cues.lastMinute=true;notify('Pizza, time left: '+fmt(t.duration-e)+'.');saveTimers();}
if(e>=t.duration&&!t.cues.finish){t.cues.finish=true;t.running=false;t.elapsed=t.duration;notify('Pizza, time is up. Check the top and bottom now.');saveTimers();}
}
function checkTimer(t,id){const e=t.elapsed+Math.max(0,Math.floor((Date.now()-t.start)/1000));let changed=false;
if(e>=(t.pull||45)&&!t.cues.pull){t.cues.pull=true;notify('Pizza #'+id+': check initial puff and pull back if needed.',false,id);changed=true;}
const turn=t.turn||120;const slot=turn>0?Math.floor(e/turn):0;
if(slot>0 && !t.cues['turn'+slot] && e<t.duration){t.cues['turn'+slot]=true;notify('Pizza '+id+', rotate if needed. Check the rim.',false,id);changed=true;}
if(e>=Math.floor(t.duration/2)&&!t.cues.halfway&&e<t.duration){t.cues.halfway=true;notify('Pizza '+id+', time left: '+fmt(t.duration-e)+'.',false,id);changed=true;}
if(t.duration-e<=60&&t.duration-e>0&&!t.cues.lastMinute){t.cues.lastMinute=true;notify('Pizza '+id+', time left: '+fmt(t.duration-e)+'.',false,id);changed=true;}
if(e>=t.duration&&!t.cues.finish){t.cues.finish=true;t.running=false;t.elapsed=t.duration;notify('Pizza '+id+', time is up. Check the pizza.',false,id);changed=true;}
if(changed)saveTimers();}
setInterval(updateTimerUI,300);
function startTimer(){if(!state.activeEvidence){toast('Create a pizza evidence record first.',true);return;}let duration=+($('#timerDuration')?.value||480),pull=+($('#pullCue')?.value||45),turn=+($('#turnCue')?.value||120);if(duration<10||duration>3600||pull<5||turn<10){toast('Check your timer settings.',true);return;}state.timer.duration=duration;state.timer.pull=pull;state.timer.turn=turn;state.pull=pull;state.turn=turn;state.timer.testId=state.activeEvidence;if(!state.timer.running){state.timer.elapsed=0;state.timer.cues={};state.timer.wallStart=null;}state.timer.start=Date.now();state.timer.wallStart=state.timer.start;state.timer.running=true;saveTimers();state.voice=$('#voiceToggle')?.checked??true;state.sound=true;log('Pizza timer started · '+fmt(duration));beep();updateTimerUI();}
async function stopTimer(source='manual'){
 if(!state.activeEvidence)throw Error('Select a pizza evidence record first.');
 const t=state.timer;
 if(!t.running){toast('The timer is not running.',true);return;}
 const actual=elapsed();t.elapsed=actual;t.running=false;
 t.cues.stopped=true;saveTimers();
 log('Pizza timer stopped · '+fmt(actual),state.activeEvidence,source);
 if(actual>=10 && actual<=3600){await api('finishEvidence',{evidence_id:state.activeEvidence,bake_seconds:actual});await refresh();}
 toast('Pizza timer stopped at '+fmt(actual));updateTimerUI();
}
function updateMicStatus(){const el=$('#micStatus');if(el){el.textContent=state.listening?'● Listening':state.wantsListen?'Connecting…':'Microphone off';el.className='pill'+(state.listening?' green':'');}}
function interpretVoice(transcript){
 const text=String(transcript||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
 state.lastTranscript=text;
 const heard=$('#lastHeard');if(heard)heard.textContent='Heard: '+text;
 if(!text||Date.now()<state.speakingUntil)return;
 const profile=state.data.voice_profile||{};
 const wake=(profile.wake_phrase||'pizza').toLowerCase().trim();
 const matchWake=text===wake||text.startsWith(wake+' ');
 if((profile.require_wake===undefined||+profile.require_wake) && !matchWake)return;
 const command=matchWake?text.slice(wake.length).trim():text;
 const alias=(profile.start_alias||'').trim().toLowerCase();
 if(/^(start (the )?(pizza )?(bake )?timer|start time|start cooking|start bake timer|start pizza timer)$/.test(command) || (alias && command===alias)){
  if(state.timer.running)return;
  startTimer();log('Voice command: start timer',state.activeEvidence,'voice_command');
  return;
 }
 if(/^(stop (the )?(pizza )?(bake )?timer|stop time|finish (the )?(pizza )?(bake )?timer)$/.test(command)){
  stopTimer('voice_command').catch(e=>toast(e.message,true));return;
 }
 // Rotation and time-left are proactive agent ANNOUNCEMENTS, not inbound user commands.
}
function startListening(){
 const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!Recognition){toast('Speech recognition is unavailable in this browser. Use the timer buttons.',true);return;}
 if(state.wantsListen)return;
 const rec=new Recognition();rec.lang=state.data.voice_profile?.language||'en-US';
 rec.interimResults=false;rec.maxAlternatives=1;rec.continuous=true;
 rec.onstart=()=>{state.listening=true;updateMicStatus();};
 rec.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)interpretVoice(e.results[i][0].transcript);};
 rec.onerror=e=>{if(!['no-speech','aborted'].includes(e.error)){toast('Voice recognition: '+e.error,true);if(['not-allowed','service-not-allowed','audio-capture'].includes(e.error))state.wantsListen=false;}};
 rec.onend=()=>{state.listening=false;updateMicStatus();if(state.wantsListen&&state.page==='live'&&document.visibilityState==='visible'){
   setTimeout(()=>{if(state.wantsListen&&!state.listening){try{rec.start();}catch{state.wantsListen=false;updateMicStatus();}}},450);
 }};
 state.recognizer=rec;state.wantsListen=true;
 try{rec.start();toast('Voice enabled: say “'+(state.data.voice_profile?.wake_phrase||'Pizza')+', start timer”.');}catch(e){state.wantsListen=false;state.recognizer=null;toast('Cannot start voice recognition: '+e.message,true);}
 updateMicStatus();
}
function stopListening(){state.wantsListen=false;state.listening=false;try{state.recognizer?.abort();}catch{}state.recognizer=null;updateMicStatus();}
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){toast('Camera requires HTTPS and a compatible browser.',true);return;}if(state.stream)return;try{state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});let video=$('#liveVideo');if(!video)return;video.srcObject=state.stream;await video.play();video.style.display='block';$('#cameraEmpty').style.display='none';log('Camera started. Keep phone away from fire and heat.');}catch(e){toast('Camera unavailable: '+e.message,true);}}
function stopCamera(){clearInterval(state.scanInterval);state.scanInterval=null;state.scanner=false;if(state.stream){state.stream.getTracks().forEach(x=>x.stop());state.stream=null;}let v=$('#liveVideo');if(v){v.srcObject=null;v.style.display='none';}let ph=$('#cameraEmpty');if(ph)ph.style.display='block';}
async function snapshot(){let v=$('#liveVideo');if(!v||!state.stream||!v.videoWidth)throw Error('Start camera and point it at the pizza first.');let c=document.createElement('canvas');const w=Math.min(1100,v.videoWidth);c.width=w;c.height=Math.max(1,Math.round(w*v.videoHeight/v.videoWidth));c.getContext('2d').drawImage(v,0,0,c.width,c.height);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.80));if(!blob)throw Error('Could not capture frame');return new File([blob],`pizza-${Date.now()}.jpg`,{type:'image/jpeg'});}
async function cameraUpload(kind){try{let image=await snapshot();await upload(image,kind);toast(kind+' view saved to evidence #'+state.activeEvidence);}catch(e){toast(e.message,true);}}
async function scannerScan(){if(state.scanning)return;if(!state.activeEvidence){toast('Create/select evidence first.',true);return;}state.scanning=true;let btn=$('#scanNow');if(btn){btn.disabled=true;btn.textContent='Analyzing…';}try{let image=await snapshot();await upload(image,'scan');let j=await api('analyze',{evidence_id:state.activeEvidence,kind:'live'});state.scans++;state.lastAnalysis=j.analysis;let result=$('#scanResult');if(result)result.innerHTML=formatAnalysis(j.analysis);log('AI scan: '+j.analysis.summary);if(j.analysis.warning)toast(j.analysis.warning,true);if(j.analysis.turn_now)notify('Visual scan suggests checking the flame-facing rim for a turn.');}catch(e){toast(e.message,true);if(/limit|cooldown/i.test(e.message)){state.scanner=false;let x=$('#autoScan');if(x)x.checked=false;clearInterval(state.scanInterval);}}finally{state.scanning=false;if(btn){btn.disabled=false;btn.textContent='◎ Analyze current frame';}}}
function toggleAutoScan(on){state.scanner=on;clearInterval(state.scanInterval);if(on){if(!state.stream){toast('Start the camera before enabling automatic scans.',true);state.scanner=false;$('#autoScan').checked=false;return;}if(!state.data.settings.key_configured){toast(window.PIZZA_LAB.role==='super_admin'?'Add your Claude API key in settings.':'Ask your Super Admin to configure the Claude API key.',true);state.scanner=false;$('#autoScan').checked=false;return;}toast('Auto-scanning enabled. One Claude vision request every 30 seconds, up to 12 stored frames per test.');state.scanInterval=setInterval(()=>{if(state.page==='live'&&state.stream&&document.visibilityState==='visible')scannerScan();},30000);}else{toast('Auto-scanning disabled.');}}
async function startNote(){stopListening();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Audio recording unsupported by this browser.',true);return;}try{const s=await navigator.mediaDevices.getUserMedia({audio:true});const supported=['audio/mp4','audio/webm','audio/ogg'].find(m=>MediaRecorder.isTypeSupported(m));state.mediaRecorder=new MediaRecorder(s,supported?{mimeType:supported}:undefined);state.audioChunks=[];state.recorded=null;state.mediaRecorder.ondataavailable=e=>{if(e.data.size)state.audioChunks.push(e.data);};state.mediaRecorder.onstop=()=>{s.getTracks().forEach(t=>t.stop());let m=state.mediaRecorder.mimeType||'audio/mp4';state.recorded=new Blob(state.audioChunks,{type:m});const a=$('#notePreview');if(a){a.src=URL.createObjectURL(state.recorded);a.style.display='block';}const save=$('#saveNote');if(save)save.disabled=false;const rec=$('#recordNote');if(rec){rec.disabled=false;rec.textContent='● Re-record note';rec.classList.remove('recording');}const stop=$('#stopNote');if(stop)stop.disabled=true;};state.mediaRecorder.start();$('#recordNote').textContent='● Recording…';$('#recordNote').classList.add('recording');$('#recordNote').disabled=true;$('#stopNote').disabled=false;}catch(e){toast('Microphone unavailable: '+e.message,true);}}
async function saveNote(){if(!state.recorded)return;let mime=state.recorded.type;let ext=mime.includes('webm')?'webm':mime.includes('ogg')?'ogg':'m4a';let file=new File([state.recorded],'pizza-voice-note.'+ext,{type:mime});await upload(file,'audio');toast('Voice note saved');state.recorded=null;await detailView(state.activeEvidence);}
// Event delegation keeps buttons functional after re-render.
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{
if(b.dataset.moisture!==undefined){const value=b.dataset.moisture;const input=$('#cheeseMoisture');if(input)input.value=value;$$('[data-moisture]').forEach(x=>x.classList.toggle('selected',x.dataset.moisture===value));return;}if(b.dataset.page){if(b.dataset.page==='team'){await loadTeam();return;}navigate(b.dataset.page);return;}if(b.dataset.go){if(b.dataset.go==='experiments')await loadExperiments();else navigate(b.dataset.go);return;}
if(b.id==='menuToggle'){$('.sidebar').classList.toggle('open');return;}
if(b.id==='closeModal'){closeModal();return;}
if(b.id==='quickEvidence'||b.dataset.newEvidence){state.pendingBatchId=b.dataset.forBatch||null;modal('New pizza evidence',evidenceForm());syncEvidenceRecipe();return;}
if(b.dataset.newExperiment!==undefined){modal('New recipe experiment',experimentForm());return;}
if(b.dataset.experimentDetail){const res=await fetch('api.php?action=experimentDetail&id='+encodeURIComponent(b.dataset.experimentDetail),{credentials:'same-origin'}).then(x=>x.json());if(!res.ok)throw Error(res.error);state.activeExperiment=res.report;render();return;}
if(b.dataset.newBatch!==undefined){modal('Create dough batch',batchForm({recipe_id:b.dataset.newBatch||''}));return;}
if(b.dataset.editBatch){const item=batch(b.dataset.editBatch);if(!item)throw Error('Batch not found');modal('Edit dough batch',batchForm(item));return;}
if(b.dataset.batchDetail){await loadBatchDetail(+b.dataset.batchDetail);return;}
if(b.dataset.exportBatch){const b=state.activeBatch;if(!b)throw Error('Open a batch first');const output={schema:'pizza-lab/batch-process-v1',exported_at:new Date().toISOString(),batch:b};const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='pizza-batch-'+String(b.batch_code||'report').replace(/[^a-zA-Z0-9-]/g,'')+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Batch process report exported');return;}
if(b.dataset.copyBatch){await navigator.clipboard.writeText(b.dataset.copyBatch);toast('Batch code copied: '+b.dataset.copyBatch);return;}
if(b.dataset.batchEvidence){state.pendingBatchId=b.dataset.batchEvidence;modal('New pizza evidence',evidenceForm());syncEvidenceRecipe();return;}
if(b.dataset.batchEvent){const item=batch(b.dataset.batchEvent);if(!item)throw Error('Batch not found');modal('Batch update · '+item.batch_code,batchEventForm(item));return;}
if(b.dataset.recipeTimeline){state.processRecipeId=+b.dataset.recipeTimeline;navigate('process');return;}
if(b.dataset.newStep){modal('Add recipe process step',recipeStepForm(+b.dataset.newStep));return;}
if(b.dataset.addTeam!==undefined){modal('Add team member',teamMemberForm());return;}
if(b.dataset.editTeam){const u=(state.teamUsers||[]).find(x=>+x.id===+b.dataset.editTeam);if(!u)throw Error('Team member not found');modal('Edit team member',teamMemberForm(u));return;}
if(b.dataset.resetTeam){const u=(state.teamUsers||[]).find(x=>+x.id===+b.dataset.resetTeam);if(!u)throw Error('Team member not found');modal('Reset password',teamResetForm(u));return;}
if(b.dataset.editStep){const [rid,key]=b.dataset.editStep.split(':');const s=stepsFor(rid).find(s=>s.step_key===key);if(!s)throw Error('Step missing');modal('Edit process step',recipeStepForm(+rid,s));return;}
if(b.dataset.deleteStep){if(!window.confirm('Delete this step from the recipe template? Existing batch timelines will not change.'))return;const [rid,key]=b.dataset.deleteStep.split(':');await execute('deleteRecipeStep',{recipe_id:+rid,step_key:key},'Step removed from future batches');closeModal();state.processRecipeId=+rid;navigate('process');return;}
if(b.dataset.stepMove){const [rid,key,direction]=b.dataset.stepMove.split(':');await execute('moveRecipeStep',{recipe_id:+rid,step_key:key,direction},'Recipe step order updated');state.processRecipeId=+rid;render();return;}
if(b.dataset.batchStep){const batch=state.activeBatch;if(!batch)throw Error('Open a batch first');const s=(batch.planned_steps||[]).find(s=>s.step_key===b.dataset.batchStep);if(!s)throw Error('Step missing from frozen plan');modal('Batch step · '+s.title,batchStepForm(batch,s));return;}
if(b.dataset.containerAdd){modal('Add dough mass / split',containerForm(state.activeBatch));return;}
if(b.dataset.tempAdd){modal('Log proofing temperature',tempForm(state.activeBatch));return;}
if(b.dataset.usageAdd){modal('Log dough balling / use',usageForm(state.activeBatch));return;}
if(b.dataset.wasteAdd){modal('Log dough waste',wasteForm(state.activeBatch));return;}

if(b.dataset.batchFilter!==undefined){state.batchFilter=b.dataset.batchFilter;render();return;}
if(b.dataset.editRecipe){let r=b.dataset.editRecipe==='new'?{}:recipe(b.dataset.editRecipe);modal(r?.id?'Edit recipe':'Create recipe',recipeForm(r||{}));return;}
if(b.dataset.clone){const j=await execute('cloneRecipe',{id:+b.dataset.clone},'Recipe variation created');modal('Edit new variation',recipeForm(recipe(j.id)));render();return;}
if(b.dataset.detail){await detailView(+b.dataset.detail);return;}
if(b.dataset.editEvidence){state.pendingBatchId=null;modal('Edit pizza evidence',evidenceForm(state.detail));syncEvidenceRecipe();return;}
if(b.id==='analyzeEvidence'){b.disabled=true;b.textContent='Analyzing photos…';try{let r=await api('analyze',{evidence_id:state.activeEvidence,kind:'evidence'});toast('AI report saved');await detailView(state.activeEvidence);}finally{b.disabled=false;b.textContent='Analyze top / bottom photos';}return;}
if(b.id==='recordNote'){await startNote();return;}if(b.id==='stopNote'){if(state.mediaRecorder?.state==='recording')state.mediaRecorder.stop();return;}if(b.id==='saveNote'){await saveNote();return;}
if(b.id==='startCamera'){await startCamera();return;}if(b.id==='stopCamera'){stopCamera();return;}if(b.id==='shotTop'||b.id==='shotBottom'){await cameraUpload(b.id==='shotTop'?'top':'bottom');return;}
if(b.id==='scanNow'){await scannerScan();return;}
if(b.id==='startTimer'){startTimer();return;}if(b.id==='stopTimer'){await stopTimer();return;}if(b.id==='listenStart'){startListening();return;}if(b.id==='listenStop'){stopListening();return;}if(b.id==='pauseTimer'){if(state.timer.running){state.timer.elapsed=elapsed();state.timer.running=false;saveTimers();log('Timer paused.');b.textContent='Resume';}else{state.timer.start=Date.now();state.timer.wallStart=state.timer.wallStart||state.timer.start;state.timer.running=true;saveTimers();log('Timer resumed.');b.textContent='Pause';}return;}
if(b.id==='resetTimer'){state.timer={running:false,start:0,elapsed:0,duration:state.timer.duration,pull:state.timer.pull||state.pull,turn:state.timer.turn||state.turn,cues:{},testId:state.activeEvidence};state.timers[String(state.activeEvidence)]=state.timer;saveTimers();log('Timer reset.');updateTimerUI();return;}
if(b.id==='finishPizza'){const actual=elapsed();state.timer.elapsed=actual;state.timer.running=false;saveTimers();if(actual>=10&&actual<=3600){await api('finishEvidence',{evidence_id:state.activeEvidence,bake_seconds:actual});await refresh();}log('Pizza marked finished · '+fmt(actual));await detailView(state.activeEvidence);return;}
if(b.id==='logReading'){let id=state.activeEvidence;if(!id)throw Error('Select evidence first');await api('reading',{evidence_id:id,phase:$('#readingPhase').value,stone_f:$('#stoneReading').value,elapsed_seconds:state.timer.wallStart?Math.min(7200,Math.max(0,Math.floor((Date.now()-state.timer.wallStart)/1000))):0});log('Stone check '+$('#stoneReading').value+'°F');toast('Heat-gun reading saved');return;}
if(b.id==='seeReadings'){await detailView(state.activeEvidence);return;}
if(b.id==='soundTest'){state.voice=true;notify('Pizza Lab reminder test. Pizza, rotate if needed. Pizza, time left: one minute.');return;}
if(b.id==='logout'){let r=await fetch('auth.php?logout=1',{method:'POST',headers:{'X-CSRF-Token':window.PIZZA_LAB.csrf}}); // sign-out uses POST + CSRF header
state.timers={};try{localStorage.removeItem(timerStorageKey);}catch{}window.location.href='auth.php';return;}
}catch(err){toast(err.message||'Action failed',true);}});
document.addEventListener('submit',async e=>{let f=e.target;if(!['recipeForm','evidenceForm','batchForm','batchEventForm','readingForm','settingsForm','voiceProfileForm','recipeStepForm','batchStepForm','containerForm','batchTempForm','batchUsageForm','batchWasteForm','teamMemberForm','teamResetForm','myPasswordForm','experimentForm'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button[type=submit],button:not([type])');if(b)b.disabled=true;try{let o=formDataObj(f);if(f.id==='experimentForm'){const j=await execute('createExperiment',o,'Variation and experiment created');closeModal();state.activeExperiment=null;await loadExperiments();return;}if(f.id==='evidenceForm' && o.batch_id){const b=batch(o.batch_id);if(!b)throw Error('Batch not found');o.recipe_id=b.recipe_id;}if(f.id==='recipeForm'){await execute('saveRecipe',o,'Recipe saved');closeModal();navigate('recipes');}
else if(f.id==='evidenceForm'){const result=await execute('saveEvidence',o,'Pizza evidence saved');closeModal();state.pendingBatchId=null;await detailView(result.id);}
else if(f.id==='batchForm'){const result=await execute('saveBatch',o,'Batch saved · '+(o.label||'Dough batch'));closeModal();state.activeBatch=null;await loadBatchDetail(result.id);}
else if(f.id==='batchEventForm'){await execute('batchEvent',o,'Batch update saved');closeModal();await loadBatchDetail(+o.batch_id);}
else if(f.id==='recipeStepForm'){await execute('saveRecipeStep',o,'Recipe process step saved');closeModal();state.processRecipeId=+o.recipe_id;navigate('process');}
else if(['batchStepForm','containerForm','batchTempForm','batchUsageForm','batchWasteForm'].includes(f.id)){const action=({batchStepForm:'saveBatchStep',containerForm:'addContainer',batchTempForm:'batchTemperature',batchUsageForm:'batchUsage',batchWasteForm:'batchWaste'})[f.id];await execute(action,o,'Batch production record saved');closeModal();await loadBatchDetail(+o.batch_id);}

else if(f.id==='teamMemberForm'){
 const action=o.id?'updateTeamMember':'createTeamMember';
 await api(action,o);closeModal();toast(o.id?'Team member updated':'Team member created');await loadTeam();
}
else if(f.id==='teamResetForm'){
 await api('resetTeamPassword',o);closeModal();toast('Team password reset');await loadTeam();
}
else if(f.id==='myPasswordForm'){
 await api('changeMyPassword',o);f.reset();toast('Your password was updated.');
}
else if(f.id==='readingForm'){await api('reading',o);await detailView(state.activeEvidence);toast('Temperature reading saved');}
else if(f.id==='settingsForm'){await execute('saveSettings',o,'Settings saved');navigate('settings');}
else if(f.id==='voiceProfileForm'){o.require_wake=f.querySelector('[name=require_wake]').checked?1:0;await execute('saveVoiceProfile',o,'Voice profile saved');navigate('settings');}}
catch(err){toast(err.message,true);}finally{if(b)b.disabled=false;}});
document.addEventListener('change',async e=>{let t=e.target;try{if(t.classList.contains('media-upload')&&t.files?.[0]){toast('Uploading '+t.dataset.kind+'…');await upload(t.files[0],t.dataset.kind);await detailView(state.activeEvidence);toast('Media saved');}if(t.id==='liveEvidence'){state.activeEvidence=+t.value;selectTimer(state.activeEvidence);state.lastAnalysis=null;log('Selected evidence #'+t.value);if($('#scanResult'))$('#scanResult').innerHTML='<p class="muted small">Select Scan to analyze this pizza.</p>';if($('#timerDuration'))$('#timerDuration').value=state.timer.duration;if($('#pullCue'))$('#pullCue').value=state.timer.pull||45;if($('#turnCue'))$('#turnCue').value=state.timer.turn||120;updateTimerUI();}if(t.id==='evidenceBatch'){syncEvidenceRecipe();}if(t.id==='batchFilterSelect'){state.batchFilter=t.value;render();}if(t.id==='batchMakerFilterSelect'){state.batchMakerFilter=t.value;render();}if(t.id==='autoScan')toggleAutoScan(t.checked);if(t.id==='voiceToggle')state.voice=t.checked;if(t.id==='recordOvenLoad'){const control=$('#loadControl'),slider=$('#ovenLoad');if(control)control.hidden=!t.checked;if(slider)slider.disabled=!t.checked;}}
catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{if(e.target.id==='ovenLoad'){let x=$('#loadLabel');if(x)x.textContent=e.target.value;}if(e.target.id==='voiceRate'){const x=$('#rateLabel');if(x)x.textContent=e.target.value;}});
$('#closeModal').addEventListener('click',closeModal);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){stopListening();if(state.scanner){state.scanner=false;clearInterval(state.scanInterval);}}if(document.visibilityState==='visible'&&state.timer.running&&elapsed()>=state.timer.duration){updateTimerUI();toast('Timer elapsed while app was backgrounded; check pizza immediately.',true);}});
window.addEventListener('pagehide',()=>{stopCamera();stopListening();});
(async()=>{try{let stored=localStorage.getItem(timerStorageKey);if(stored){let t=JSON.parse(stored);if(t&&typeof t==='object'&&!Array.isArray(t)){for(let [id,x] of Object.entries(t)){if(/^\d+$/.test(id)&&x&&Number.isFinite(+x.duration)&&+x.duration>=10&&+x.duration<=3600&&Number.isFinite(+x.elapsed)&&x.cues&&typeof x.cues==='object'){state.timers[id]=x;}}}}}catch{}try{await refresh();render();}catch(e){$('#view').innerHTML=`<div class="danger">${esc(e.message)}</div>`;}})();

